global.FRankDays.placeStructureNatively = function (server, structShortId, sx, sy, sz) {
  if (typeof global.FRankDays.isFcraftSourceProtected === 'function' && global.FRankDays.isFcraftSourceProtected(server)) return { ok: false, reason: 'fcraft_v9_original_terrain_protected', id: structShortId };
  var bundle = global.FRankDays.COMPILED_VILLAGE_BUNDLE;
  if (!bundle || !bundle.structures || !bundle.structures[structShortId]) {
    return { ok: false, reason: 'missing_compiled_structure', id: structShortId };
  }
  if (!server || !server.runCommandSilent) {
    return { ok: true, dry_run: true, id: structShortId };
  }

  var pal = bundle.palette;
  var st = bundle.structures[structShortId];
  var spans = st.spans || [];
  var signs = st.signs || [];
  var cmdCount = 0;

  for (var i = 0; i < spans.length; i++) {
    var sp = spans[i];
    var blockState = pal[sp[0]];
    var x1 = sx + sp[1];
    var y1 = sy + sp[2];
    var z1 = sz + sp[3];
    var x2 = sx + sp[4];
    var y2 = sy + sp[5];
    var z2 = sz + sp[6];
    if (x1 === x2 && y1 === y2 && z1 === z2) {
      server.runCommandSilent('setblock ' + x1 + ' ' + y1 + ' ' + z1 + ' ' + blockState);
    } else {
      server.runCommandSilent('fill ' + x1 + ' ' + y1 + ' ' + z1 + ' ' + x2 + ' ' + y2 + ' ' + z2 + ' ' + blockState);
    }
    cmdCount += 1;
  }

  for (var j = 0; j < signs.length; j++) {
    var sg = signs[j];
    var sgX = sx + sg[0];
    var sgY = sy + sg[1];
    var sgZ = sz + sg[2];
    var sgCol = sg[3] || 'white';
    var sgGlow = sg[4] ? '1b' : '0b';
    var msgs = sg[5] || [];
    var m0 = JSON.stringify(msgs[0] || '{"text":""}');
    var m1 = JSON.stringify(msgs[1] || '{"text":""}');
    var m2 = JSON.stringify(msgs[2] || '{"text":""}');
    var m3 = JSON.stringify(msgs[3] || '{"text":""}');
    server.runCommandSilent(
      'data merge block ' + sgX + ' ' + sgY + ' ' + sgZ +
      ' {is_waxed:1b,front_text:{has_glowing_text:' + sgGlow + ',color:"' + sgCol + '",messages:[' + m0 + ',' + m1 + ',' + m2 + ',' + m3 + ']}}'
    );
    cmdCount += 1;
  }

  return { ok: true, id: structShortId, spans_executed: spans.length, signs_applied: signs.length, commands: cmdCount };
};

